WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM payments), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT id, method, amount, paid_at, status, is_new_session, session_no FROM sessionized ORDER BY session_no NULLS LAST;
